function genPhysiqueEtStretching() {
  const out = [];
  let pi = 0, idN = 1;
  const nextPlayer = (session, extra = {}) => {
    const [name, flag, sex] = PHYS_POOL[pi % PHYS_POOL.length]; pi++;
    const form = 74 + ((pi * 5) % 20);
    return {
      id: "ph" + (idN++), name, flag, sex,
      age: 14 + (pi % 5), form,
      utr: (8 + (pi % 4) + (pi % 2) * 0.5).toFixed(1),
      itf: sex === "F" ? "J" + (300 + pi * 6) : "" + (180 + pi * 8),
      sleep: 7 + (pi % 3) * 0.3, hrv: 62 + (pi % 20), fatigue: "low", stress: "low", load: "optimale",
      serviceTrend: (pi % 6) - 1, testToday: false,
      objectifsMois: [], exercices: [], focus: { axis: "", note: "" },
      session, detail: mkDetail({ indice: form }), ...extra,
    };
  };

  // Physique — 14h00-15h30, réparti sur les 2 salles
  ["Salle physique 1", "Salle physique 2"].forEach(salle => {
    for (let k = 0; k < 3; k++) {
      out.push(nextPlayer({ time: "14:00", end: "15:30", type: "Physique — Renforcement", court: salle, status: "recuperation", coach: "Thomas (prépa)", coachPhone: "" }));
    }
  });

  // Physique — 15h30-17h00, réparti sur les 2 salles
  ["Salle physique 1", "Salle physique 2"].forEach(salle => {
    for (let k = 0; k < 3; k++) {
      out.push(nextPlayer({ time: "15:30", end: "17:00", type: "Physique — Explosivité", court: salle, status: "recuperation", coach: "Thomas (prépa)", coachPhone: "" }));
    }
  });

  // Stretching — 17h00, 3 groupes
  const stretchingCoachs = ["Thomas (prépa)", "Marie", "Rodolphe"];
  const stretchingLieux = ["Salle physique 1", "Salle physique 2", "Court 1"];
  stretchingLieux.forEach((lieu, gi) => {
    for (let k = 0; k < 3; k++) {
      out.push(nextPlayer({ time: "17:00", end: "17:30", type: `Stretching — Groupe ${gi + 1}`, court: lieu, status: "recuperation", coach: stretchingCoachs[gi], coachPhone: "" }));
    }
  });

  return out;
}
