/* Ajoute un nombre de jours à une date "DD/MM/YYYY" et renvoie une chaîne au même format */
function addDaysFR(dateStr, days) {
  const d = parseFRDate(dateStr);
  d.setDate(d.getDate() + days);
  return d.toLocaleDateString("fr-FR", { day: "2-digit", month: "2-digit", year: "numeric" });
}

/* Génère 3 stages récurrents chaque semaine, du 1er septembre 2026 au 31 août 2027 */
function genStagesRecurrents() {
  const templates = [
    { key: "hn25", nom: "Stage Haut Niveau — 25h", type: "Haut niveau", duree: "25h d'entraînement", niveauMin: "15/5", places: 4, tarif: 850, coach: "Rodolphe", lieu: "Courts 1-2" },
    { key: "hn30", nom: "Stage Haut Niveau — 30h", type: "Haut niveau", duree: "30h d'entraînement", niveauMin: "15/1", places: 4, tarif: 1250, coach: "Rodolphe", lieu: "Courts 3-4" },
    { key: "data", nom: "Stage Data Human Fab", type: "Data", duree: "", niveauMin: "", places: 4, tarif: 2600, coach: "Thomas (prépa)", lieu: "Studio Human Fab" },
  ];
  const start = "01/09/2026";
  const end = new Date(2027, 7, 31); // 31/08/2027
  const out = [];
  templates.forEach(tpl => {
    let du = start;
    let n = 1;
    while (parseFRDate(du) <= end) {
      const au = addDaysFR(du, 6);
      out.push({
        id: `stg-${tpl.key}-${n}`, nom: tpl.nom, type: tpl.type, du, au,
        places: tpl.places, tarif: tpl.tarif, coach: tpl.coach, lieu: tpl.lieu,
        duree: tpl.duree, niveauMin: tpl.niveauMin, hebergement: true, hebergementTarif: 0, participants: [],
      });
      du = addDaysFR(du, 7);
      n++;
    }
  });
  return out;
}
STAGES_SEED.push(...genStagesRecurrents());

