/* ---------- Le cerveau : analyse d'un joueur ---------- */
function analyze(p) {
  const flags = [];
  if (p.fatigue === "high") flags.push({ kind: "risk", level: "high", label: "Fatigue musculaire élevée" });
  if (p.sleep != null && p.sleep < 6) flags.push({ kind: "risk", level: "high", label: `Sommeil insuffisant (${p.sleep} h)` });
  if (p.load === "surcharge") flags.push({ kind: "risk", level: "high", label: "Charge en surcharge" });
  if (p.hrv != null && p.hrv < 55) flags.push({ kind: "risk", level: "med", label: `HRV basse (${p.hrv} ms)` });
  if (p.stress === "high") flags.push({ kind: "risk", level: "med", label: "Stress élevé" });
  if (p.load === "élevée") flags.push({ kind: "risk", level: "med", label: "Charge élevée" });
  if (p.form != null && p.form < 75) flags.push({ kind: "watch", level: "med", label: `Forme en baisse (${p.form}%)` });
  if (p.serviceTrend != null && p.serviceTrend >= 8) flags.push({ kind: "progress", level: "good", label: `Progression service +${p.serviceTrend}%` });
  if (p.session && p.session.status === "competition") flags.push({ kind: "info", level: "info", label: "Compétition aujourd'hui" });

  const highs = flags.filter(f => f.level === "high").length;
  const meds = flags.filter(f => f.level === "med").length;
  const hasProgress = flags.some(f => f.kind === "progress");
  const isComp = p.session && p.session.status === "competition";

  let severity = "ok";
  if (highs > 0) severity = "high";
  else if (meds > 0) severity = "med";
  else if (hasProgress) severity = "good";
  else if (isComp) severity = "info";

  let reco;
  if (highs > 0) reco = "Séance allégée ou récupération — surveiller la charge de près.";
  else if (isComp) reco = "Activation courte + routine d'avant-match.";
  else if (meds > 0) reco = "Adapter l'intensité et contrôler les signaux du jour.";
  else if (hasProgress) reco = "Sur sa lancée — maintenir la charge et affiner la finition.";
  else reco = "RAS — séance normale prévue.";

  let focusSuggestion = null;
  if (highs > 0) focusSuggestion = "Récupération";
  else if (isComp) focusSuggestion = "Tactique";
  else if (hasProgress) focusSuggestion = "Service";
  else if (p.form != null && p.form < 75) focusSuggestion = "Physique";

  const score = highs * 1000 + meds * 100 + (isComp ? 50 : 0) + (hasProgress ? 5 : 0);
  return { flags, severity, reco, score, focusSuggestion };
}

/* ---------- Petits utilitaires ---------- */
const initials = (name) =>
  name.split(" ").map(w => w[0]).slice(0, 2).join("").toUpperCase();

const sevColor = (s) =>
  s === "high" ? T.red : s === "med" ? T.amber : s === "good" ? T.green : s === "info" ? T.blue : T.dim;

const statusMeta = {
  entrainement: { label: "Entraînement", color: T.green },
  competition: { label: "Compétition", color: T.blue },
  recuperation: { label: "Récupération", color: T.amber },
};

const todayLabel = () => {
  const d = new Date();
  const s = d.toLocaleDateString("fr-FR", { weekday: "long", day: "numeric", month: "long", year: "numeric" });
  return s.charAt(0).toUpperCase() + s.slice(1);
};

/* ---------- Semaines ISO (pour l'onglet Stages) ---------- */
function parseFRDate(str) {
  if (!str) return null;
  const [d, m, y] = str.split("/").map(n => parseInt(n, 10));
  if (!d || !m || !y) return null;
  return new Date(y, m - 1, d);
}
function isoWeekInfo(date) {
  const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
  const dayNum = d.getUTCDay() || 7;
  d.setUTCDate(d.getUTCDate() + 4 - dayNum);
  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  const week = Math.ceil(((d - yearStart) / 86400000 + 1) / 7);
  const monday = new Date(d); monday.setUTCDate(d.getUTCDate() - 3);
  const sunday = new Date(monday); sunday.setUTCDate(monday.getUTCDate() + 6);
  const fmt = (x) => x.toLocaleDateString("fr-FR", { day: "2-digit", month: "2-digit", timeZone: "UTC" });
  return {
    week, year: d.getUTCFullYear(), start: fmt(monday), end: fmt(sunday),
    monthIndex: monday.getUTCMonth(), monthYear: monday.getUTCFullYear(),
  };
}
function stageWeekInfo(stage) {
  const d = parseFRDate(stage.du);
  return d ? isoWeekInfo(d) : { week: null, year: null, start: "", end: "" };
}

function reminderText(p) {
  const coach = (p.session && p.session.coach) || "Coach";
  const time = (p.session && p.session.time) || "";
  const court = (p.session && p.session.court) || "";
  const objs = (p.objectifsMois || []).filter(Boolean);
  const exs = (p.exercices || []).filter(Boolean).slice(0, 3);
  let msg = `Bonjour ${coach}, rappel séance ${time}${court ? " · " + court : ""} avec ${p.name}.`;
  if (objs.length) msg += `\nObjectifs du mois : ${objs.join(" ; ")}.`;
  if (exs.length) msg += `\nExercices : ${exs.join(", ")}.`;
  msg += `\nBon entraînement ! — CADART Tennis Academy`;
  return msg;
}

/* Un seul SMS par coach, regroupant toutes ses séances du jour */
function coachReminderText(coach, players) {
  const bySlot = {};
  players.forEach(p => {
    const time = (p.session && p.session.time) || "";
    const end = (p.session && p.session.end) || "";
    const court = (p.session && p.session.court) || "";
    const type = (p.session && p.session.type) || "";
    const key = `${time}|${end}|${court}|${type}`;
    if (!bySlot[key]) bySlot[key] = { time, end, court, type, names: [] };
    bySlot[key].names.push(p.name);
  });
  const slots = Object.values(bySlot).sort((a, b) => a.time.localeCompare(b.time));
  let msg = `Bonjour ${coach}, voici tes séances du jour (${slots.length} créneau${slots.length > 1 ? "x" : ""}) :`;
  slots.forEach(s => {
    msg += `\n• ${s.time}${s.end ? `–${s.end}` : ""} · ${s.court}${s.type ? " · " + s.type : ""} : ${s.names.join(", ")}`;
  });
  msg += `\nBon entraînement ! — CADART Tennis Academy`;
  return msg;
}

/* ============================================================
   COMPOSANT PRINCIPAL
   ============================================================ */
class ErrorBoundary extends React.Component {
  constructor(props) { super(props); this.state = { err: null }; }
  static getDerivedStateFromError(err) { return { err }; }
  componentDidCatch(err, info) { console.error("Dashboard error:", err, info); }
  render() {
    if (this.state.err) {
      return (
        <div style={{ minHeight: "100vh", background: T.bg, color: T.text, fontFamily: FONT, display: "flex", alignItems: "center", justifyContent: "center", padding: 24 }}>
          <div style={{ maxWidth: 460, textAlign: "center" }}>
            <div style={{ fontSize: 18, fontWeight: 700, marginBottom: 8 }}>Oups — un souci d'affichage</div>
            <div style={{ color: T.mute, fontSize: 13.5, lineHeight: 1.5 }}>
              Le tableau de bord a rencontré une erreur : {String((this.state.err && this.state.err.message) || this.state.err)}
            </div>
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}

export default function App() {
  // Mode TV : ?tv=1 dans l'URL affiche le planning du jour en plein écran, sans connexion.
  // Pratique pour un navigateur de salon/TV laissé allumé à l'académie — pas besoin de se logger chaque jour.
  const isTV = typeof window !== "undefined" && new URLSearchParams(window.location.search).get("tv") === "1";
  if (isTV) return <ErrorBoundary><TVPlanningView /></ErrorBoundary>;
  return <ErrorBoundary><AuthGate /></ErrorBoundary>;
}

