function Cockpit({ players, analyzed, priorities, competitionPlayers, facilityGroups, onOpenPlayer, onGoPlanning, depenses, stages, role }) {
  const eur = (n) => "€" + Math.round(n).toLocaleString("fr-FR");
  const joueurs = players.length;
  const seances = players.filter(p => p.session && p.session.time && p.session.status !== "competition").length;
  const tests = players.filter(p => p.testToday).length;
  const enComp = competitionPlayers.length;

  // Remplissage des courts (vrai calcul depuis le planning)
  const courtSet = {};
  players.forEach(p => {
    const c = p.session && p.session.court;
    if (c && !/salle/i.test(c) && p.session.time) {
      if (!courtSet[c]) courtSet[c] = new Set();
      courtSet[c].add(p.session.time);
    }
  });
  const usedSlots = Object.values(courtSet).reduce((a, s) => a + s.size, 0);
  const capacity = COURTS.length * SLOTS.length;
  const remplissage = capacity ? Math.round(usedSlots / capacity * 100) : 0;

  // Performance
  const indiceMoyen = joueurs ? Math.round(players.reduce((a, p) => a + ((p.detail && p.detail.indice) || p.form || 0), 0) / joueurs) : 0;
  let wins = 0, losses = 0;
  players.forEach(p => ((p.detail && p.detail.resultats) || []).forEach(r => (r.win ? wins++ : losses++)));
  const enProgression = players.filter(p => (p.detail && p.detail.indiceDelta > 0) || p.serviceTrend >= 8).length;
  const vitrine = [...players].sort((a, b) => (b.serviceTrend || 0) - (a.serviceTrend || 0)).filter(p => (p.serviceTrend || 0) > 0).slice(0, 3);

  // Santé business — chiffres réels du dernier mois renseigné dans l'onglet Tableau de bord financier
  const moisDisponibles = [...new Set((depenses || []).map(d => d.mois).filter(Boolean))].sort((a, b) => moisSortKey(a) - moisSortKey(b));
  const MOIS_BUSINESS = moisDisponibles[moisDisponibles.length - 1] || moisLabelNow();
  const revenuJoueurs = players.reduce((a, p) => a + (p.tarifMensuel || 0), 0);
  const playersSansTarif = players.filter(p => !p.tarifMensuel || p.tarifMensuel <= 0).length;
  const revenuStages = caStagesMois(stages, MOIS_BUSINESS);
  const depensesMois = (depenses || []).filter(d => d.mois === MOIS_BUSINESS);
  // Montants déjà signés (+ recette, − dépense) : le CA réel du mois = tout ce qui est entré en banque,
  // les dépenses réelles = tout ce qui est sorti. On ajoute le CA stages séparément (pas dans les dépenses).
  const recettesReellesMois = depensesMois.filter(d => (d.montant || 0) > 0).reduce((a, d) => a + d.montant, 0);
  const depensesReellesMois = depensesMois.filter(d => (d.montant || 0) < 0).reduce((a, d) => a + d.montant, 0); // négatif
  const caMois = revenuStages + recettesReellesMois; // recettes réelles bancaires + revenu stages
  const marge = caMois + depensesReellesMois; // depensesReellesMois déjà négatif
  const margePct = caMois ? Math.round((marge / caMois) * 100) : 0;
  // Remplissage courts : vrai calcul (ci-dessus). Impayés : pas de suivi mensuel réel des paiements
  // joueurs pour l'instant — on affiche à la place les joueurs sans tarif renseigné (donnée réelle).

  // Rendement par coach : revenu des enfants gérés − prestation versée au coach
  const coachMap = {};
  players.forEach(p => {
    const coachName = (p.session && p.session.coach) || "Non assigné";
    if (!coachMap[coachName]) coachMap[coachName] = [];
    coachMap[coachName].push(p);
  });
  const prestationsCoachs = dernieresPrestationsCoachs(depenses);
  const coachRendement = Object.entries(coachMap).map(([name, list]) => {
    const revenu = list.reduce((a, p) => a + (p.tarifMensuel || 0), 0);
    const salaire = prestationsCoachs[name] || 0;
    const rendement = revenu - salaire;
    const margePct = revenu ? Math.round((rendement / revenu) * 100) : 0;
    return { name, nbEnfants: list.length, revenu, salaire, rendement, margePct };
  }).sort((a, b) => b.rendement - a.rendement);

  // Effectif — entrées réelles du mois (basé sur la date d'inscription renseignée sur chaque fiche)
  const aujourdHui = new Date();
  const entreesCeMois = players.filter(p => {
    const d = parseFRDate(p.dateInscription);
    return d && d.getMonth() === aujourdHui.getMonth() && d.getFullYear() === aujourdHui.getFullYear();
  }).length;
  const filles = players.filter(p => p.sex === "F").length;
  const garcons = players.length - filles;
  const ageMoyen = joueurs ? Math.round(players.reduce((a, p) => a + (p.age || 0), 0) / joueurs) : 0;

  return (
    <main style={styles.main}>
      <header style={styles.header}>
        <div>
          <div style={styles.h1}>Tableau de bord</div>
          <div style={styles.sub}>{todayLabel()} · Rodolphe Cadart, Directeur</div>
        </div>
        <button style={styles.primaryBtn} onClick={onGoPlanning}><CalendarDays size={16} /> Voir le planning</button>
      </header>

      {/* 1. Le pouls du jour */}
      <div style={styles.ckSection}><div style={styles.ckTitle}>Le pouls du jour</div></div>
      <div style={styles.kpiRow}>
        <Stat icon={Activity} label="Séances aujourd'hui" value={seances} />
        <Stat icon={FlaskConical} label="Tests prévus" value={tests} tint={T.blue} />
        <Stat icon={AlertTriangle} label="Alertes actives" value={priorities.length} tint={priorities.length ? T.amber : T.dim} subColor={T.amber} />
        <Stat icon={Trophy} label="En compétition" value={enComp} tint={T.blue} />
      </div>

      {/* 2. Santé business (réservé à la direction) */}
      {role === "admin" && (
        <>
          <div style={{ ...styles.ckSection, marginTop: 28 }}>
            <div style={styles.ckTitle}>Santé business</div>
            <span style={styles.ckNote}>CA, marge et remplissage : chiffres réels de {MOIS_BUSINESS}</span>
          </div>
          <div style={styles.kpiRow}>
            <Stat
              icon={Euro} label={`CA réel · ${MOIS_BUSINESS}`} value={eur(caMois)}
              sub={`${eur(recettesReellesMois)} recettes bancaires + ${eur(revenuStages)} stages`}
              subColor={T.mute}
            />
            <Stat icon={Wallet} label={`Marge · ${MOIS_BUSINESS}`} value={eur(marge)} sub={caMois ? `${margePct}% du CA` : "—"} subColor={marge >= 0 ? T.green : T.red} tint={marge >= 0 ? T.green : T.red} />
            <Stat icon={PieChart} label="Remplissage courts" value={`${remplissage}%`} sub={`${usedSlots}/${capacity} créneaux`} subColor={remplissage >= 75 ? T.green : T.amber} tint={remplissage >= 75 ? T.green : T.amber} />
            <Stat
              icon={AlertTriangle} label="Joueurs sans tarif renseigné" value={playersSansTarif}
              sub={playersSansTarif > 0 ? "à corriger dans leur fiche" : "tous renseignés ✓"}
              subColor={playersSansTarif > 0 ? T.amber : T.green} tint={playersSansTarif > 0 ? T.amber : T.green}
            />
          </div>
        </>
      )}

      {/* 3. Performance sportive */}
      <div style={{ ...styles.ckSection, marginTop: 28 }}><div style={styles.ckTitle}>Performance sportive</div></div>
      <div style={styles.cols}>
        <div style={{ flex: 2, minWidth: 300 }}>
          <div style={styles.kpiRow}>
            <Stat icon={Award} label="Indice global moyen" value={indiceMoyen} sub="+2 ce mois" />
            <Stat icon={Trophy} label="Bilan résultats" value={`${wins}V – ${losses}D`} sub="ce mois" subColor={T.green} />
            <Stat icon={TrendingUp} label="En progression" value={enProgression} sub="joueurs en hausse" />
          </div>
        </div>
        <section style={{ ...styles.panel, flex: 1, minWidth: 260 }}>
          <div style={styles.panelHead}><span style={styles.panelTitle}>Joueurs vitrine</span><Sparkles size={16} color={T.green} /></div>
          {vitrine.length === 0 ? <div style={styles.emptyPanel}>Aucune progression marquée.</div> : vitrine.map(p => (
            <div key={p.id} style={styles.vitrineRow} onClick={() => onOpenPlayer(p)}>
              <span style={{ ...styles.avatarSm, background: `${T.green}18`, color: T.green, borderColor: `${T.green}33` }}>{initials(p.name)}</span>
              <span style={{ flex: 1, fontSize: 13, fontWeight: 600 }}>{p.flag} {p.name}</span>
              <span style={{ fontSize: 12.5, fontWeight: 700, color: T.green }}>+{p.serviceTrend}% service</span>
            </div>
          ))}
        </section>
      </div>

      {/* 4. Effectif & fidélisation */}
      <div style={{ ...styles.ckSection, marginTop: 28 }}>
        <div style={styles.ckTitle}>Effectif</div>
        <span style={styles.ckNote}>entrées basées sur la date d'inscription renseignée sur chaque fiche</span>
      </div>
      <div style={styles.kpiRow}>
        <Stat icon={Users} label="Joueurs actifs" value={joueurs} sub={`${ageMoyen} ans en moyenne`} subColor={T.mute} />
        <Stat icon={UserPlus} label="Entrées ce mois" value={entreesCeMois} sub="date d'inscription ce mois-ci" subColor={T.mute} />
        <Stat icon={Users} label="Filles" value={filles} sub={joueurs ? `${Math.round(filles / joueurs * 100)}% de l'effectif` : "—"} subColor={T.mute} />
        <Stat icon={Users} label="Garçons" value={garcons} sub={joueurs ? `${Math.round(garcons / joueurs * 100)}% de l'effectif` : "—"} subColor={T.mute} />
      </div>

      {/* 5. Rendement par coach (financier, réservé à la direction) */}
      {role === "admin" && (
        <>
          <div style={{ ...styles.ckSection, marginTop: 28 }}>
            <div style={{ ...styles.ckTitle, fontSize: 12 }}>Rendement par coach</div>
            <span style={{ ...styles.ckNote, fontSize: 11 }}>revenu des enfants gérés − prestation versée au coach</span>
          </div>
          <section style={{ ...styles.panel, padding: 10 }}>
            {coachRendement.length === 0 ? (
              <div style={{ ...styles.emptyPanel, fontSize: 12.5, padding: "16px 0" }}>Aucun coach assigné pour le moment.</div>
            ) : coachRendement.map(c => (
              <div key={c.name} style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 6px", borderBottom: `1px solid ${T.border}` }}>
                <span style={{ ...styles.avatarSm, background: `${T.green}18`, color: T.green, borderColor: `${T.green}33` }}>
                  {initials(c.name)}
                </span>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: 12.5, fontWeight: 600 }}>{c.name}</div>
                  <div style={{ fontSize: 10.5, color: T.mute, marginTop: 1 }}>
                    {c.nbEnfants} enfant{c.nbEnfants > 1 ? "s" : ""} · {eur(c.revenu)} générés · {eur(c.salaire)} versés
                  </div>
                </div>
                <div style={{ textAlign: "right" }}>
                  <div style={{ fontSize: 12.5, fontWeight: 800, color: c.rendement >= 0 ? T.green : T.red }}>
                    {c.rendement >= 0 ? "+" : ""}{eur(c.rendement)}
                  </div>
                  <div style={{ fontSize: 10, fontWeight: 700, color: T.mute, marginTop: 1 }}>{c.margePct}% de marge</div>
                </div>
              </div>
            ))}
          </section>
        </>
      )}

      {/* 6. Priorités du jour (en bas) */}
      <div style={{ ...styles.ckSection, marginTop: 28 }}><div style={styles.ckTitle}>Priorités du jour</div></div>
      <section style={styles.panel}>
        <div style={styles.panelHead}>
          <span style={styles.panelTitle}>Priorités du jour</span>
          <span onClick={onGoPlanning} style={{ fontSize: 12.5, fontWeight: 700, color: T.green, cursor: "pointer", display: "inline-flex", alignItems: "center", gap: 4 }}>
            Voir le planning <ArrowRight size={14} />
          </span>
        </div>
        {priorities.length === 0 ? (
          <div style={styles.emptyPanel}>Aucune alerte ce matin — l'académie est au vert. 🎾</div>
        ) : priorities.map(p => {
          const c = sevColor(p.a.severity);
          const reason = (p.a.flags.find(f => f.kind === "risk") || {}).label;
          return (
            <div key={p.id} style={styles.vitrineRow} onClick={() => onOpenPlayer(p)}>
              <span style={{ ...styles.avatarSm, background: `${c}22`, color: c, borderColor: `${c}44` }}>{initials(p.name)}</span>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 13, fontWeight: 600 }}>{p.flag} {p.name}</div>
                <div style={{ fontSize: 11.5, color: T.mute }}>{reason || "À surveiller"}</div>
              </div>
              <span style={{ ...styles.statusPill, background: `${c}1c`, color: c }}>{p.a.severity === "high" ? "Risque élevé" : "À surveiller"}</span>
            </div>
          );
        })}
      </section>

      <footer style={styles.footer}>CADART Tennis Academy · Cockpit directeur — les données sont enregistrées automatiquement.</footer>
    </main>
  );
}

function JoueursView({ analyzed, onOpen, onEdit, onDelete, onAdd }) {
  const [q, setQ] = useState("");
  const [sortBy, setSortBy] = useState("nom");
  const filtered = q.trim()
    ? analyzed.filter(p => p.name.toLowerCase().includes(q.trim().toLowerCase()))
    : analyzed;

  const list = [...filtered].sort((a, b) => {
    if (sortBy === "age") return (a.age || 0) - (b.age || 0);
    if (sortBy === "classement") return classementRangIndex(a.classementFFT) - classementRangIndex(b.classementFFT);
    if (sortBy === "score") return scoreGlobal(b.detail) - scoreGlobal(a.detail);
    return nomDeFamille(a.name).localeCompare(nomDeFamille(b.name)) || a.name.localeCompare(b.name);
  });

  return (
    <main style={styles.main}>
      <header style={styles.header}>
        <div>
          <div style={styles.h1}>Joueurs</div>
          <div style={styles.sub}>{analyzed.length} joueur{analyzed.length > 1 ? "s" : ""} enregistré{analyzed.length > 1 ? "s" : ""}</div>
        </div>
        <div style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
          <input
            style={{ ...styles.input, width: 220 }}
            placeholder="Rechercher un joueur…"
            value={q}
            onChange={(e) => setQ(e.target.value)}
          />
          <Select
            value={sortBy}
            onChange={setSortBy}
            options={[["nom", "Trier : nom (A-Z)"], ["age", "Trier : âge"], ["classement", "Trier : classement"], ["score", "Trier : meilleur score"]]}
          />
          <button style={styles.primaryBtn} onClick={onAdd}><Plus size={17} /> Ajouter un joueur</button>
        </div>
      </header>

      <section style={styles.panel}>
        {list.length === 0 ? (
          <div style={styles.emptyPanel}>
            {analyzed.length === 0
              ? "Aucun joueur pour l'instant. Ajoute ton premier joueur, ou importe-les depuis l'onglet Planning (bouton « Importer CSV »)."
              : "Aucun joueur ne correspond à cette recherche."}
          </div>
        ) : (
          <div>
            {list.map(p => (
              <PlayerRow key={p.id} p={p} onOpen={() => onOpen(p)} onEdit={() => onEdit(p)} onDelete={() => onDelete(p.id)} />
            ))}
          </div>
        )}
      </section>

      <footer style={styles.footer}>CADART Tennis Academy · Joueurs — les données sont enregistrées automatiquement.</footer>
    </main>
  );
}

