/* ============================================================
   FICHE JOUEUR (profil détaillé)
   ============================================================ */
function Ring({ value, size = 54, stroke = 6, color = T.green }) {
  const r = (size - stroke) / 2;
  const circ = 2 * Math.PI * r;
  const v = Math.max(0, Math.min(100, value || 0));
  const off = circ * (1 - v / 100);
  return (
    <svg width={size} height={size} style={{ flexShrink: 0 }}>
      <circle cx={size / 2} cy={size / 2} r={r} stroke={T.border} strokeWidth={stroke} fill="none" />
      <circle cx={size / 2} cy={size / 2} r={r} stroke={color} strokeWidth={stroke} fill="none"
        strokeDasharray={circ} strokeDashoffset={off} strokeLinecap="round"
        transform={`rotate(-90 ${size / 2} ${size / 2})`} />
      <text x="50%" y="52%" textAnchor="middle" dominantBaseline="middle" fill={T.text} fontSize={size * 0.3} fontWeight="800">{v}%</text>
    </svg>
  );
}

const scoreColor = (v) => (v >= 85 ? T.green : v >= 70 ? T.amber : T.red);

function ScoreRow({ label, value, bench }) {
  const deficit = bench != null ? Math.max(0, bench - value) : 0;
  const surplus = bench != null ? Math.max(0, value - bench) : 0;
  const gapColor = bench == null ? T.text : deficit === 0 ? T.green : deficit <= 5 ? T.amber : T.red;
  return (
    <div style={{ marginBottom: 13 }}>
      <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5, marginBottom: 5, alignItems: "baseline" }}>
        <span style={{ color: T.mute }}>{label}</span>
        <span style={{ display: "flex", alignItems: "baseline", gap: 8 }}>
          <span style={{ fontWeight: 800 }}>{value}</span>
          {bench != null && (
            <span style={{ fontSize: 11, fontWeight: 700, color: gapColor }}>
              {deficit === 0 ? (surplus > 0 ? `+${surplus}` : "au niveau") : `-${deficit}`}
            </span>
          )}
        </span>
      </div>
      <div style={styles.scoreTrack}>
        <div style={{ ...styles.scoreFill, width: `${value}%`, background: scoreColor(value) }} />
        {bench != null && (
          <div style={{ ...styles.benchMark, left: `${bench}%` }} title={`Top 50 mondial : ${bench}`} />
        )}
      </div>
    </div>
  );
}

function MetricRow({ label, value, unit, max, bench }) {
  if (value == null) return null;
  const pct = max ? Math.min(100, Math.round((value / max) * 100)) : 0;
  const benchPct = bench != null && max ? Math.min(100, Math.round((bench / max) * 100)) : null;
  const gapColor = benchPct == null ? T.text : pct >= benchPct ? T.green : pct >= benchPct * 0.85 ? T.amber : T.red;
  const diff = bench != null ? +(value - bench).toFixed(1) : null;
  return (
    <div style={{ marginBottom: 13 }}>
      <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5, marginBottom: 5, alignItems: "baseline" }}>
        <span style={{ color: T.mute }}>{label}</span>
        <span style={{ display: "flex", alignItems: "baseline", gap: 8 }}>
          <span style={{ fontWeight: 800 }}>{value}{unit}</span>
          {diff != null && (
            <span style={{ fontSize: 11, fontWeight: 700, color: gapColor }}>
              {diff === 0 ? "au niveau" : diff > 0 ? `+${diff}${unit}` : `${diff}${unit}`}
            </span>
          )}
        </span>
      </div>
      <div style={styles.scoreTrack}>
        <div style={{ ...styles.scoreFill, width: `${pct}%`, background: gapColor === T.text ? scoreColor(pct) : gapColor }} />
        {benchPct != null && (
          <div style={{ ...styles.benchMark, left: `${benchPct}%` }} title={`Top 50 mondial : ${bench}${unit}`} />
        )}
      </div>
    </div>
  );
}

